import re, glob

def check(path):
    svg = open(path).read()
    m = re.search(r'viewBox="0 0 (\d+) (\d+)"', svg)
    W, H = int(m.group(1)), int(m.group(2))
    problems = []
    # check text elements stay in bounds
    for t in re.finditer(r'<text x="([-\d.]+)" y="([-\d.]+)"', svg):
        x, y = float(t.group(1)), float(t.group(2))
        if x < -5 or x > W + 5 or y < 0 or y > H + 5:
            problems.append(f"text out of bounds: ({x:.0f},{y:.0f})")
    # check rects
    for r in re.finditer(r'<rect x="([-\d.]+)" y="([-\d.]+)" width="([-\d.]+)" height="([-\d.]+)"', svg):
        x, y, w, h = map(float, r.groups())
        if x < -5 or y < -5 or x + w > W + 5 or y + h > H + 5:
            problems.append(f"rect out of bounds: ({x:.0f},{y:.0f},{w:.0f},{h:.0f})")
    # negative heights are a real bug
    for r in re.finditer(r'<rect x="([-\d.]+)" y="([-\d.]+)" width="([-\d.]+)" height="([-\d.]+)"', svg):
        h = float(r.group(4))
        if h < 0:
            problems.append(f"negative height rect: {r.group(0)}")
    print(f"{path}: {'OK' if not problems else 'ISSUES'}")
    for p in problems[:10]:
        print("   ", p)

for f in sorted(glob.glob("chart_*.svg")):
    check(f)

# Sanity: verify key data values appear in the SVGs
checks = {
    "chart_inflation_growth.svg": ["9.2%", "2.4%", "0.4%", "3.4%"],
    "chart_growth_divergence.svg": ["3.2", "-0.3", "2.5", "EU total"],
    "chart_trade.svg": ["198B", "8B", "42.6", "79.1", "-84.2"],
    "chart_debt.svg": ["134.8", "104.3", "112", "62.9", "51.3"],
    "chart_unemployment.svg": ["11.3%", "6.1%", "3.4%", "3.0%"],
}
print("\nValue presence checks:")
for f, vals in checks.items():
    svg = open(f).read()
    for v in vals:
        status = "OK" if v in svg else "MISSING"
        print(f"  {f}: {v} -> {status}")
